// Generate packages/core/src/rules/advisory-data.ts from advisories/SKA-*.json.
// Run with --check to fail (exit 1) when the generated file is stale.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const dir = 'advisories';
const out = join('packages', 'core', 'src', 'rules', 'advisory-data.ts');
const files = readdirSync(dir)
  .filter((f) => /^SKA-\d{4}-\d{4}\.json$/.test(f))
  .sort();

const index = {};
const domains = {};
for (const file of files) {
  const advisory = JSON.parse(readFileSync(join(dir, file), 'utf8'));
  for (const domain of advisory.indicators?.domains ?? []) {
    const key = domain.toLowerCase();
    const existing = domains[key];
    if (existing && existing.id >= advisory.id) continue;
    domains[key] = { id: advisory.id, severity: advisory.severity, title: advisory.title };
  }
  for (const skill of advisory.skills ?? []) {
    if (skill.genericName) continue;
    const name = skill.name.toLowerCase();
    if (!/^[a-z0-9][a-z0-9._-]*$/.test(name)) continue;
    const existing = index[name];
    if (existing && existing.id >= advisory.id) continue;
    index[name] = { id: advisory.id, severity: advisory.severity, title: advisory.title };
  }
}

const entries = Object.keys(index)
  .sort()
  .map((name) => `  [${JSON.stringify(name)}, ${JSON.stringify(index[name])}],`)
  .join('\n');

const domainEntries = Object.keys(domains)
  .sort()
  .map((domain) => `  [${JSON.stringify(domain)}, ${JSON.stringify(domains[domain])}],`)
  .join('\n');

const content = `// Generated by scripts/generate-advisory-data.mjs — do not edit by hand.
import type { Severity } from '../types.js';

export interface AdvisoryEntry {
  id: string;
  severity: Severity;
  title: string;
}

export const ADVISORY_NAME_INDEX: ReadonlyMap<string, AdvisoryEntry> = new Map([
${entries}
]);

export const ADVISORY_DOMAIN_INDEX: ReadonlyMap<string, AdvisoryEntry> = new Map([
${domainEntries}
]);
`;

if (process.argv.includes('--check')) {
  const current = readFileSync(out, 'utf8');
  if (current !== content) {
    console.error(`✗ ${out} is stale — run: node scripts/generate-advisory-data.mjs`);
    process.exit(1);
  }
  console.log(`✓ ${out} is up to date (${Object.keys(index).length} names, ${Object.keys(domains).length} domains).`);
} else {
  writeFileSync(out, content);
  console.log(`✓ wrote ${out} (${Object.keys(index).length} names, ${Object.keys(domains).length} domains).`);
}
